(109,1,'2026-05-26 08:47:48','2026-05-26 06:47:48','<!-- wp:group {\"metadata\":{\"categories\":[\"twentytwentyfive_page\",\"banner\",\"featured\"],\"patternName\":\"twentytwentyfive/page-link-in-bio-wide-margins\",\"name\":\"Lien dans la bio avec profil, liens et des marges externes larges\"},\"align\":\"wide\",\"className\":\"is-style-section-1\",\"style\":{\"dimensions\":{\"minHeight\":\"100vh\"},\"spacing\":{\"padding\":{\"right\":\"var:preset|spacing|80\",\"left\":\"var:preset|spacing|80\",\"top\":\"var:preset|spacing|80\",\"bottom\":\"var:preset|spacing|80\"},\"margin\":{\"top\":\"0\",\"bottom\":\"0\"}}},\"layout\":{\"type\":\"constrained\",\"justifyContent\":\"center\"}} -->\n<div class=\"wp-block-group alignwide is-style-section-1\" style=\"min-height:100vh;margin-top:0;margin-bottom:0;padding-top:var(--wp--preset--spacing--80);padding-right:var(--wp--preset--spacing--80);padding-bottom:var(--wp--preset--spacing--80);padding-left:var(--wp--preset--spacing--80)\"><!-- wp:group {\"layout\":{\"type\":\"flex\",\"orientation\":\"vertical\",\"justifyContent\":\"stretch\"}} -->\n<div class=\"wp-block-group\"><!-- wp:heading {\"style\":{\"typography\":{\"textAlign\":\"center\"}}} -->\n<h2 class=\"wp-block-heading has-text-align-center\">Pour mieux me connaitre</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Nous somme a votre disposition pour vous aider</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><a href=\"https://localhost\">Lien vers wordpress https</a></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><a href=\"https://localhost:8080\" data-type=\"link\" data-id=\"http://localhost:8001\">Lien vers mon Portfolios</a></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><a href=\"http://localhost/wp-admin\" data-type=\"link\" data-id=\"http://localhost/wp-admin\">Lien vers la page d\'administration</a></p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group -->\n\n<!-- wp:paragraph -->\n<p><a href=\"https://localhost:8081/\">Lien vers le my sql</a></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Ex de realisation : </p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><a href=\"http://localhost/mon-projet-pas-a-pas/\" data-type=\"page\" data-id=\"24\">Lien vers la page de blog</a></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:html -->\n<form method=\"POST\" action=\"../contact\">\n    <label for=\"nom\">Nom  </label>\n    <input id=\"nom\" type=\"string\" name=\"nom\">\n    <br>\n    <label for=\"email\">Email</label>\n    <input id=\"email\" type=\"email\" name=\"email\">\n    <br>\n    <label for=\"objet\">Objet</label>\n    <input id=\"objet\" type=\"string\" name=\"objet\">\n    <br>\n    <input id=\"submit\" type=\"submit\" name=\"ajouter\" class=\"submit\" value=\"Envoyer\">\n</form>\n<!-- /wp:html --></div>\n<!-- /wp:group -->','Accueil','','inherit','closed','closed','','19-revision-v1','','','2026-05-26 08:47:48','2026-05-26 06:47:48','',19,'http://localhost/?p=109',0,'revision','',0),
