INSERT INTO `wp_xyz_ips_short_code` VALUES
(1,'versPHP','Affiche la version de Php','<?php\r\nphpinfo();','[xyz-ips snippet=\"versPHP\"]',1,2,0,0),
(2,'requetteSQL','','<?php\r\n// Select contient la requÔö£┬¼te SQL\r\n$select = \"SELECT post_title, guid, post_date FROM wp_posts WHERE\r\npost_type=\'page\'\";\r\n// Exécute cette requÔö£┬¼te sur la base de donnée Wordpress représentée par $wpdb\r\n$resultats = $wpdb->get_results($select);\r\n// La commande echo dit Ôö£├í php d\'écrire <table> dans le code html qu\'il génÔö£┬┐re\r\necho \"<table border=1>\";\r\n// Pour chaque $ligne de mon tableau $resultats\r\nforeach($resultats as $ligne){\r\n// Ecrire <tr><td> dans mon code html\r\n    echo \"<tr><td>\";\r\n    // Ecrire le champ post_title\r\n    echo $ligne->post_title;\r\n    // Passe Ôö£├í la colonne suivante\r\n    echo \"</td><td>\";\r\n    // Ecrire le champ post_date\r\n    echo $ligne->post_date;\r\n    // Passe Ôö£├í la colonne suivante\r\n    echo \"</td><td>\";\r\n    // Créer un lien\r\n    echo \"<a href=\";\r\n    echo $ligne->guid;\r\n    echo \">lien</a>\";\r\n    // Passe Ôö£├í la ligne suivante\r\n    echo \"</td></tr><br>\";\r\n    }\r\n// Fin de la table\r\necho \"</table>\";','[xyz-ips snippet=\"requetteSQL\"]',1,2,0,0),
(3,'contact','','<?php\r\nglobal $wpdb;\r\n\r\n// Exécute le code si le bouton ajouter est cliqué\r\nif (isset($_POST[\'ajouter\'])) {\r\n\r\n    // Récupération directe des données du formulaire sans filtrage\r\n    $nom   = $_POST[\'nom\'];\r\n    $email = $_POST[\'email\'];\r\n    $objet = $_POST[\'objet\'];\r\n\r\n    // Construction de la requÔö£┬¼te SQL en concaténation directe (Vulnérable aux injections)\r\n    // On suppose que ta table s\'appelle \'contact\'\r\n    $sql = \"INSERT INTO contact (nom, email, objet) VALUES (\'$nom\', \'$email\', \'$objet\')\";\r\n\r\n    // Exécution de la requÔö£┬¼te\r\n    $wpdb->query($sql);\r\n\r\n    // Affichage de la requÔö£┬¼te pour tes tests\r\n    echo \"RequÔö£┬¼te : $sql\";\r\n}\r\n?>','[xyz-ips snippet=\"contact\"]',1,2,0,0),
(4,'Voir-php','','<?php\r\nglobal $wpdb;\r\n\r\n$sql = \"SELECT cle, nom, email, objet FROM contact\";\r\n$resultats = $wpdb->get_results($sql);\r\n\r\necho \"<table border=\'1\'>\";\r\necho \"<tr><th>Clé</th><th>Nom</th><th>Email</th><th>Objet</th></tr>\";\r\n\r\nforeach ($resultats as $ligne) {\r\n    echo \"<tr>\";\r\n    echo \"<td>\" . $ligne->cle . \"</td>\";\r\n    echo \"<td>\" . $ligne->nom . \"</td>\";\r\n    echo \"<td>\" . $ligne->email . \"</td>\";\r\n    echo \"<td>\" . $ligne->objet . \"</td>\";\r\n    echo \"</tr>\";\r\n}\r\n\r\necho \"</table>\";\r\n?>','[xyz-ips snippet=\"Voir-php\"]',1,2,0,0),
(5,'formulairecommande','','<?php\r\nglobal $wpdb;\r\n$prestations = $wpdb->get_results(\"SELECT id, libelle, tarif FROM prestations\");\r\n\r\necho \'<form method=\"POST\" action=\"../traitement-commande/\">\'; \r\necho \'<label for=\"nom_client\"><strong>Nom de l\\\'entreprise / Client :</strong></label><br>\';\r\necho \'<input type=\"text\" id=\"nom_client\" name=\"nom_client\" required><br><br>\';\r\necho \'<h3>Sélectionnez vos besoins :</h3>\';\r\n\r\nforeach ($prestations as $p) {\r\n    echo \'<div style=\"margin-bottom: 10px;\">\';\r\n    echo \'<input type=\"checkbox\" id=\"prest_\'.$p->id.\'\" name=\"prestations[]\" value=\"\'.$p->id.\'\"> \';\r\n    echo \'<label for=\"prest_\'.$p->id.\'\">\' . esc_html($p->libelle) . \' - <strong>\' . $p->tarif . \' ├öé┬╝</strong></label>\';\r\n    echo \'</div>\';\r\n}\r\necho \'<br><input type=\"submit\" name=\"commander\" value=\"Estimer et Commander\">\';\r\necho \'</form>\';\r\n?>','[xyz-ips snippet=\"formulairecommande\"]',1,2,0,0),
(6,'traitement-commande','','<?php\r\nglobal $wpdb;\r\nif (isset($_POST[\'commander\']) && !empty($_POST[\'nom_client\']) && !empty($_POST[\'prestations\'])) {\r\n    $nom_client = sanitize_text_field($_POST[\'nom_client\']); \r\n    $prestations_choisies = $_POST[\'prestations\']; \r\n    $total = 0;\r\n\r\n    echo \"<h2>Récapitulatif de l\'intervention pour : \" . esc_html($nom_client) . \"</h2><ul>\";\r\n\r\n    foreach ($prestations_choisies as $id_prest) {\r\n        $id_prest = intval($id_prest);\r\n        $prest_details = $wpdb->get_row($wpdb->prepare(\"SELECT libelle, tarif FROM prestations WHERE id = %d\", $id_prest));\r\n\r\n        if ($prest_details) {\r\n            echo \"<li>\" . esc_html($prest_details->libelle) . \" : \" . $prest_details->tarif . \" ├öé┬╝</li>\";\r\n            $total += $prest_details->tarif;\r\n            $wpdb->query($wpdb->prepare(\"INSERT INTO commandes (nom_client, prestation_id) VALUES (%s, %d)\", $nom_client, $id_prest));\r\n        }\r\n    }\r\n    echo \"</ul><h3 style=\'color: green;\'>Total estimé : \" . $total . \" ├öé┬╝</h3>\";\r\n}\r\n?>','[xyz-ips snippet=\"traitement-commande\"]',1,2,0,0),
(7,'liste-commandes','','<?php\r\nglobal $wpdb;\r\n$query = \"SELECT c.nom_client, p.libelle, p.tarif, c.date_commande FROM commandes c JOIN prestations p ON c.prestation_id = p.id ORDER BY c.nom_client ASC, c.date_commande DESC\";\r\n$resultats = $wpdb->get_results($query);\r\n\r\nif ($resultats) {\r\n    echo \"<table border=\'1\' style=\'width:100%;\'><tr><th>Client</th><th>Prestation</th><th>Tarif</th><th>Date</th></tr>\";\r\n    foreach ($resultats as $row) {\r\n        echo \"<tr><td>\" . esc_html($row->nom_client) . \"</td><td>\" . esc_html($row->libelle) . \"</td><td>\" . $row->tarif . \" ├öé┬╝</td><td>\" . $row->date_commande . \"</td></tr>\";\r\n    }\r\n    echo \"</table>\";\r\n}\r\n?>','[xyz-ips snippet=\"liste-commandes\"]',1,2,0,0);
